comments.suggestion_code:
$incomplete = ($rows.Count -ne $seedList.Count)
if ($incomplete) { $nFail = [Math]::Max($nFail, 1) }
$summary += "# 结论 : $(if ($nFail -eq 0 -and -not $incomplete) { 'REGRESSION PASSED' } else { 'REGRESSION FAILED' })"

if (-not (Get-Command vlib -ErrorAction SilentlyContinue)) {
  Write-Host "[VRF_AXIL] 未找到 vlib，请确认 ModelSim 环境变量/路径，终止。"
  Exit-With 5
}
vlib $libName | Out-Null
if ($LASTEXITCODE -ne 0) {

$proc = Start-Process -FilePath $psExe.Source -ArgumentList $argList -NoNewWindow -PassThru -ErrorAction SilentlyContinue
if (-not $proc) {
  Write-Host "[VRF_AXIL][ERROR] seed=$s 子进程启动失败，该轮判为失败。"
  $rows += [pscustomobject]@{ Seed = $s; Exit = "n/a"; Checks = 0; Failures = 0; AssertErr = 0; Verdict = "RUN_ERROR"; Note = "子进程启动失败" }
  $nFail++; $failSeeds += $s
  continue
}
